style.css:
@-moz-document domain("pikidiary.lol") {
body {
    font-family: 'Helvetica Neue', Helvetica, Arial, 'Arial Unicode MS', sans-serif;
    background: url("https://files.catbox.moe/8gyvex.png");
    font-size: 12.5px;
}

span, a, input, textarea, .bio, .profile-grid-label, strong, em, small, p {
    font-family: 'Helvetica Neue', Helvetica, Arial, 'Arial Unicode MS', sans-serif;
}

.post-content {
    border: 1px solid #CCC;
    -webkit-box-shadow:2px 2px 2px rgba(85,85,85,0.6);
	border-radius: 5px;
    color: #111;
    background: #FFF;
}
.avatar {
    -webkit-box-shadow:2px 2px 2px rgba(85,85,85,0.6);
	border-radius: 5px;
}
.avatar-small {
    -webkit-box-shadow:2px 2px 2px rgba(85,85,85,0.6);
	border-radius: 5px;
    
}
.tab {
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fcc);
    -webkit-box-shadow:2px 2px 2px rgba(85,85,85,0.6);
    border-radius: 5px;
}
.tab:hover {
    border: 1px solid #fcc;
    background: linear-gradient(#fee, #fcc);
    -webkit-box-shadow:2px 2px 2px rgba(85,85,85,0.6);
    border-radius: 8px;
}
.tab.active {
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fcc);
}
.tab.active:hover {
    border: 1px solid #fcc;
    background: linear-gradient(#fee, #fcc);
}
.tab-cont {
    padding: 5px 0px 5px 0px;
}
.post-box textarea {
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fee);

    border-radius: 5px;    
}
.action-button-gray {
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fcc);
    color: #111;
    border-radius: 5px;    
}
.action-button-gray:hover {
    border: 1px solid #fcc;
    background: linear-gradient(#fee, #fcc);
    border-radius: 8px;  
}
body > main > div > div.prof-main > div.tabs > div:nth-child(2) {
    border-color: #fcc !important;
}
.profile-grid-label {
    border-color: #fcc !important;    
}
.bar {
    border-color: #fcc !important;      
}
header {
    border-color: #fcc !important;    
}
.char-counter {
        border-color: #fcc !important;
}
button {
    font-family: 'Helvetica Neue', Helvetica, Arial, 'Arial Unicode MS', sans-serif;
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fcc);
    color: #111;
    border-radius: 5px;       
    padding: 5px;
}
button:hover {
    border: 1px solid #fcc;
    background: linear-gradient(#fee, #fcc);
    border-radius: 8px;  
}
.button {
    font-family: 'Helvetica Neue', Helvetica, Arial, 'Arial Unicode MS', sans-serif;
    border: 1px solid #fcc;
    background: linear-gradient(#fff, #fcc);
    color: #111;
    border-radius: 5px;       
}
.button:hover {
    border: 1px solid #fcc;
    background: linear-gradient(#fee, #fcc);
    border-radius: 8px;  
}
.header-actions button {
    font-family: 'Cyrillic', "ＭＳ Pゴシック", "MS PGothic", sans-serif;
}
main {
    background-color: #feec;
}
.like-form .post-button {
    background: none;
    border: none;
}
}
